mapper.sql:
WHERE post.hidden_at IS NULL
  AND post.closed_early_at IS NULL
  AND post.closes_on >= #{today}
  AND program.is_source_present = TRUE

  AND post.source_code = #{sourceCode}
  AND post.source_program_id = #{sourceProgramId}

choose.when:
post.hidden_at IS NULL
AND (
    post.closed_early_at IS NOT NULL
    OR post.closes_on < #{today}
    OR program.is_source_present = FALSE
)

mapper.update:
UPDATE recruitment_post
SET closed_early_at = #{closedEarlyAt},
    updated_at = #{closedEarlyAt}
WHERE id = #{id}
  AND closed_early_at IS NULL

mapper.select:
SELECT
FROM recruitment_post post INNER JOIN company ON company.id = post.company_id INNER JOIN support_program program ON program.source_code = post.source_code AND program.source_program_id = post.source_program_id
ORDER BY post.closes_on ASC, post.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT
FROM recruitment_post post INNER JOIN company ON company.id = post.company_id INNER JOIN support_program program ON program.source_code = post.source_code AND program.source_program_id = post.source_program_id
ORDER BY post.created_at DESC, post.id DESC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE recruitment_post
SET hidden_at = #{hiddenAt},
    hidden_reason = #{hiddenReason},
    updated_at = #{hiddenAt}
WHERE id = #{id}
  AND hidden_at IS NULL

UPDATE recruitment_post
SET hidden_at = NULL,
    hidden_reason = NULL,
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND hidden_at IS NOT NULL
